import sys

data = sys.stdin.read().split()
n, K = int(data[0]), int(data[1])
a = list(map(int, data[2:2 + n]))
seen = {}
i = 0
while i < K:
    if i % n == 0:
        key = tuple(a)
        if key in seen:
            period = i - seen[key]
            i += (K - i) // period * period
            seen = {}
            if i >= K:
                break
        else:
            seen[key] = i
    idx = i % n
    a[idx] ^= a[n - 1 - idx]
    i += 1
print(' '.join(map(str, a)))

